import React, { useMemo } from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate } from '../remotionShim';
{/* Start Google Fonts Loader */}
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]); // super light + stable

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700;800;900`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */}



export type StarWarsCrawlProps = Record<string, any>;

const StarWarsCrawl: React.FC<StarWarsCrawlProps> = ({
  backgroundColor = "#000000",
  transparentBackground = false,
  durationInSeconds = 30,
  introText = "A long time ago in a galaxy far, far away....",
  introTextColor = "#4BD5EE",
  introFontSize = 65,
  crawlTitle = "EPISODE I\nTHE AUTOMATION AWAKENS",
  titleFontSize = 150,
  crawlText = "This ENTIRE animation is made using Malloy Studio with 1 line of prompt\n\n\"Recreate the animation of the Star Wars crawl opening scene\"\n\nTook like 73 seconds to generate...\n\nbut the crazier thing is, \n\nunlike other AI tools\n\nMalloy Studio let's you control the parameters of the animations.. i can type anything i want here like...\n\n67\n\ncomment \"starwars\" ill send the link to your DM so you can check it out when you are free!",
  textFontSize = 85,
  crawlTextColor = "#FFE81F",
  crawlTilt = 45,
  starCount = 400,
}) => {
  {/* Load Google Fonts */}
  useFontLoader(["Oswald", "Inter"]);
  {/* End Load Google Fonts */}

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Color logic
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Timings
  const introFadeInEnd = fps * 1.5;
  const introHoldEnd = fps * 4.5;
  const introFadeOutEnd = fps * 6;
  
  const crawlStartFrame = fps * 7;
  const crawlDuration = (durationInSeconds * fps) - crawlStartFrame;

  // Intro Opacity
  const introOpacity = interpolate(
    frame,
    [0, introFadeInEnd, introHoldEnd, introFadeOutEnd],
    [0, 1, 1, 0],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  // Crawl Y Position
  // Starts below the screen on the tilted plane, moves far into the distance
  const crawlY = interpolate(
    frame,
    [crawlStartFrame, crawlStartFrame + crawlDuration],
    [height * 1.2, -height * 4],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  // Generate static starfield to avoid re-rendering layout jumps
  const stars = useMemo(() => {
    return Array.from({ length: starCount }).map((_, i) => ({
      id: i,
      x: Math.random() * width,
      y: Math.random() * height,
      size: Math.random() * 2 + 0.5,
      baseOpacity: Math.random() * 0.5 + 0.3,
      twinkleSpeed: Math.random() * 0.05 + 0.02,
      twinklePhase: Math.random() * Math.PI * 2,
    }));
  }, [starCount, width, height]);

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, overflow: "hidden" }}>
      
      {/* Starfield Layer */}
      {!transparentBackground && (
        <AbsoluteFill style={{ transition: "none" }}>
          {stars.map((star) => {
            const currentOpacity = star.baseOpacity + Math.sin((frame * star.twinkleSpeed) + star.twinklePhase) * 0.3;
            return (
              <div
                key={star.id}
                style={{
                  position: "absolute",
                  left: star.x,
                  top: star.y,
                  width: star.size,
                  height: star.size,
                  backgroundColor: "#ffffff",
                  borderRadius: "50%",
                  opacity: Math.max(0.1, Math.min(1, currentOpacity)),
                  transition: "none",
                }}
              />
            );
          })}
        </AbsoluteFill>
      )}

      {/* Intro Text Layer */}
      {frame < introFadeOutEnd && (
        <AbsoluteFill
          style={{
            justifyContent: "center",
            alignItems: "center",
            opacity: introOpacity,
            transition: "none",
          }}
        >
          <div
            style={{
              fontFamily: "Inter, sans-serif",
              fontSize: introFontSize,
              color: introTextColor,
              letterSpacing: width * 0.002,
              fontWeight: 400,
              width: width * 0.6,
              textAlign: "left",
              transition: "none",
            }}
          >
            {introText}
          </div>
        </AbsoluteFill>
      )}

      {/* Crawl Mask & Perspective Container */}
      {frame >= crawlStartFrame - fps && (
        <AbsoluteFill
          style={{
            maskImage: "linear-gradient(to bottom, transparent 0%, rgba(0,0,0,1) 25%)",
            WebkitMaskImage: "linear-gradient(to bottom, transparent 0%, rgba(0,0,0,1) 25%)",
            transition: "none",
          }}
        >
          <AbsoluteFill
            style={{
              perspective: height * 0.8,
              display: "flex",
              justifyContent: "center",
              alignItems: "center",
              transformStyle: "preserve-3d",
              transition: "none",
            }}
          >
            {/* The Crawling Text */}
            <div
              style={{
                transform: `rotateX(${crawlTilt}deg) translateY(${crawlY}px)`,
                transformOrigin: "50% 50%",
                width: width * 0.85,
                display: "flex",
                flexDirection: "column",
                alignItems: "center",
                color: crawlTextColor,
                transition: "none",
              }}
            >
              <div
                style={{
                  fontFamily: "Oswald, sans-serif",
                  fontWeight: 800,
                  fontSize: titleFontSize,
                  textAlign: "center",
                  lineHeight: 1.2,
                  marginBottom: height * 0.1,
                  letterSpacing: width * 0.005,
                  whiteSpace: "pre-wrap",
                  transition: "none",
                }}
              >
                {crawlTitle}
              </div>

              <div
                style={{
                  fontFamily: "Inter, sans-serif",
                  fontWeight: 700,
                  fontSize: textFontSize,
                  textAlign: "center",
                  lineHeight: 1.5,
                  letterSpacing: width * 0.001,
                  whiteSpace: "pre-wrap",
                  transition: "none",
                }}
              >
                {crawlText}
              </div>
            </div>
          </AbsoluteFill>
        </AbsoluteFill>
      )}
    </AbsoluteFill>
  );
};

export default StarWarsCrawl;